def verify_binding(binding):
 c=binding['commit']
 for name,h in binding['science'].items():assert __import__('hashlib').sha256(subprocess.check_output(['git','show',c+':src/dunhuang/research/paired_benchmark_r59/'+name])).hexdigest()==h
 for name,h in binding['dependencies'].items():assert __import__('hashlib').sha256(subprocess.check_output(['git','show',c+':'+name])).hexdigest()==h

