 out=Path('reports/r59_release');assert not out.exists();data=read(ROOT/'data/manifest.json');main=read(ROOT/'main/result.json');ev=read(ROOT/'controls/result.json');diag=read(ROOT/'r58_diagnostics/result.json');verify_binding(data['binding']);verify_binding(main['binding']);verify_binding(ev['binding']);verify_binding(diag['binding'])
